package com.admin.common.engine;

import com.alibaba.fastjson.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.util.*;
import java.math.BigDecimal;
import java.util.concurrent.ConcurrentHashMap;

/** One wire model for interactive applies and DB-driven batch reconciliation. */
@Service
public class EngineSpecFactory {
    @Resource private JdbcTemplate jdbc;
    private record Policies(long at,Map<String,long[]> groups,Map<Integer,Long> speeds){}
    private final ConcurrentHashMap<Long,Policies> cache=new ConcurrentHashMap<>();
    public void invalidate(Long node){cache.remove(node);}
    private Policies policies(Long node){Policies old=cache.get(node);if(old!=null&&System.currentTimeMillis()-old.at()<1000)return old;Map<String,long[]> groups=new HashMap<>();Map<Integer,Long> speeds=new HashMap<>();for(var row:jdbc.queryForList("SELECT scope,owner_id,up_bits,down_bits FROM engine_bandwidth_group WHERE node_id=?",node))groups.put(row.get("scope")+":"+row.get("owner_id"),new long[]{((Number)row.get("up_bits")).longValue(),((Number)row.get("down_bits")).longValue()});for(var row:jdbc.queryForList("SELECT id,speed FROM speed_limit WHERE status=0 OR status=1"))speeds.put(((Number)row.get("id")).intValue(),Math.max(0,((Number)row.get("speed")).longValue())*1000000L);Policies next=new Policies(System.currentTimeMillis(),groups,speeds);cache.put(node,next);return next;}
    private static void keys(JSONObject object,String...allowed){Set<String> names=Set.of(allowed);for(String key:object.keySet())if(!names.contains(key))throw new IllegalArgumentException("unsupported engine option: "+key);}
    private static long integer(JSONObject object,String key,long fallback){Object value=object.get(key);if(value==null)return fallback;try{return new BigDecimal(value.toString()).longValueExact();}catch(Exception e){throw new IllegalArgumentException("integer required for "+key);}}
    private static long rate(JSONObject object,String key){long value=integer(object,key,0);if(value!=0&&(value<1000||value>1000000000000L))throw new IllegalArgumentException("rate must be zero or 1000..1e12 bits/second");return value;}
    public static String normalizeOptions(String text){if(text==null||text.isBlank())return null;if(text.length()>32768)throw new IllegalArgumentException("engine options exceed 32KiB");JSONObject object=JSONObject.parseObject(text);validateOptions(object);return object.isEmpty()?null:object.toJSONString();}
    public static void validateOptions(JSONObject o){
        keys(o,"listeners","targets","selection","dnsPolicy","health","egress","bandwidth","traffic");
        if(o.containsKey("traffic")){JSONObject t=o.getJSONObject("traffic");keys(t,"localOutput","localTargets","sourceMode","returnPathConfirmed");for(String key:List.of("localOutput","localTargets","returnPathConfirmed"))if(t.containsKey(key)&&!(t.get(key) instanceof Boolean))throw new IllegalArgumentException("boolean required for "+key);String mode=t.getString("sourceMode");if(mode!=null&&!Set.of("masquerade","preserve").contains(mode))throw new IllegalArgumentException("invalid source mode");if("preserve".equals(mode)!=t.getBooleanValue("returnPathConfirmed"))throw new IllegalArgumentException("source preservation requires return routing confirmation");if("preserve".equals(mode)&&o.containsKey("egress")){JSONObject e=o.getJSONObject("egress");for(String key:List.of("sourceIPv4","sourceIPv6"))if(e.getString(key)!=null&&!e.getString(key).isBlank())throw new IllegalArgumentException("source preservation conflicts with explicit SNAT");}}
        if(o.containsKey("listeners")){JSONArray rows=o.getJSONArray("listeners");if(rows==null||rows.isEmpty()||rows.size()>16)throw new IllegalArgumentException("1..16 listeners required");for(Object item:rows){JSONObject l=(JSONObject)JSONObject.toJSON(item);keys(l,"host","port","protocol","family");if(!Set.of("tcp","udp").contains(l.getString("protocol")))throw new IllegalArgumentException("TCP/UDP listener required");Endpoint endpoint=Endpoint.parse(join(l.getString("host"),integer(l,"port",0)));if(!"ip".equals(endpoint.getKind()))throw new IllegalArgumentException("listener must be numeric IP");}}
        if(o.containsKey("targets")){JSONArray rows=o.getJSONArray("targets");if(rows==null||rows.isEmpty()||rows.size()>16)throw new IllegalArgumentException("1..16 targets required");long sum=0;for(Object item:rows){JSONObject t=(JSONObject)JSONObject.toJSON(item);keys(t,"endpoint","weight");JSONObject endpoint=t.getJSONObject("endpoint");keys(endpoint,"kind","host","port","family");Endpoint.parse(join(endpoint.getString("host"),integer(endpoint,"port",0)));long weight=integer(t,"weight",1);if(weight<1||weight>32)throw new IllegalArgumentException("target weight must be 1..32");sum+=weight;}if(sum>32)throw new IllegalArgumentException("target weights exceed 32 buckets");}
        if(o.containsKey("selection")&&!Set.of("fifo","hash","round","random").contains(o.getString("selection")))throw new IllegalArgumentException("invalid target selection");
        if(o.containsKey("dnsPolicy")){JSONObject d=o.getJSONObject("dnsPolicy");keys(d,"failClosed","staleMillis","drainMillis");long stale=integer(d,"staleMillis",30000),drain=integer(d,"drainMillis",300000);if(stale<0||stale>300000||drain<1000||drain>3600000)throw new IllegalArgumentException("invalid DNS grace/drain bound");}
        if(o.containsKey("health")){JSONObject h=o.getJSONObject("health");keys(h,"protocol","port","intervalMillis","timeoutMillis","rise","fall","payload","expected");if(!Set.of("tcp","udp").contains(h.getString("protocol")))throw new IllegalArgumentException("health protocol required");long interval=integer(h,"intervalMillis",5000),timeout=integer(h,"timeoutMillis",500),rise=integer(h,"rise",2),fall=integer(h,"fall",2),port=integer(h,"port",0);if(interval<1000||interval>60000||timeout<50||timeout>3000||rise<1||rise>10||fall<1||fall>10||port<0||port>65535)throw new IllegalArgumentException("invalid health bounds");if("udp".equals(h.getString("protocol")))for(String key:List.of("payload","expected")){try{byte[] bytes=Base64.getDecoder().decode(h.getString(key));if(bytes.length<1||bytes.length>64)throw new IllegalArgumentException();}catch(Exception e){throw new IllegalArgumentException("UDP health requires bounded explicit exchange");}}}
        if(o.containsKey("egress")){JSONObject e=o.getJSONObject("egress");keys(e,"interface","sourceIPv4","sourceIPv6","gatewayIPv4","gatewayIPv6");String name=e.getString("interface");if(name==null||!name.matches("[a-zA-Z0-9_.:-]{1,15}"))throw new IllegalArgumentException("invalid egress interface");for(String key:List.of("sourceIPv4","sourceIPv6","gatewayIPv4","gatewayIPv6")){String ip=e.getString(key);if(ip==null||ip.isBlank())continue;Endpoint endpoint=Endpoint.parse(join(ip,1));if(!"ip".equals(endpoint.getKind())||!endpoint.getFamily().equals(key.endsWith("4")?"ipv4":"ipv6"))throw new IllegalArgumentException("invalid source/gateway family");}}
        if(o.containsKey("bandwidth")){JSONObject b=o.getJSONObject("bandwidth");keys(b,"upBitsPerSecond","downBitsPerSecond");rate(b,"upBitsPerSecond");rate(b,"downBitsPerSecond");}
    }
    public static String join(String host,long port){if(host==null)throw new IllegalArgumentException("host required");return (host.contains(":")?"["+host+"]":host)+":"+port;}
    public static JSONArray listeners(ForwardSpec spec,JSONObject options){
        JSONArray result=new JSONArray();if(options.containsKey("listeners")){for(Object item:options.getJSONArray("listeners")){JSONObject raw=(JSONObject)JSONObject.toJSON(item);Endpoint e=Endpoint.parse(join(raw.getString("host"),integer(raw,"port",0)));JSONObject l=e.json();l.remove("kind");l.put("protocol",raw.getString("protocol"));result.add(l);}}else{for(String protocol:List.of("tcp","udp")){String host=protocol.equals("tcp")?spec.getTunnel().getTcpListenAddr():spec.getTunnel().getUdpListenAddr();Endpoint e=Endpoint.parse(join(host,spec.getPort()));JSONObject l=e.json();l.remove("kind");l.put("protocol",protocol);result.add(l);}}
        Set<String> seen=new HashSet<>();for(Object item:result){JSONObject l=(JSONObject)item;String key=l.getString("family")+"/"+l.getString("protocol")+"/"+l.getString("host")+"/"+l.getIntValue("port");if(!seen.add(key))throw new IllegalArgumentException("duplicate listener");}return result;
    }
    public JSONObject advanced(Long node,ForwardSpec spec){return advanced(node,spec,false);}
    public JSONObject advancedForReconcile(Long node,ForwardSpec spec){return advanced(node,spec,true);}
    private JSONObject advanced(Long node,ForwardSpec spec,boolean reconcile){
        JSONObject options=spec.getEngineOptions()==null?new JSONObject():JSONObject.parseObject(normalizeOptions(spec.getEngineOptions()));if(options==null)options=new JSONObject();JSONArray targets=new JSONArray();List<String> remote=new ArrayList<>();for(String addr:spec.getTarget().split(",")){Endpoint e=Endpoint.parse(addr.trim());remote.add(join(e.getHost(),e.getPort()));JSONObject t=new JSONObject();t.put("endpoint",e.json());t.put("weight",1);targets.add(t);}if(targets.isEmpty()||targets.size()>16)throw new IllegalArgumentException("1..16 target origins required");
        if(options.containsKey("targets")){targets=options.getJSONArray("targets");List<String> specified=new ArrayList<>();for(Object t:targets){JSONObject endpoint=((JSONObject)t).getJSONObject("endpoint");specified.add(join(Endpoint.parse(join(endpoint.getString("host"),integer(endpoint,"port",0))).getHost(),integer(endpoint,"port",0)));}if(!specified.equals(remote))throw new IllegalArgumentException("remoteAddr and structured targets differ");JSONArray canonical=new JSONArray();for(Object item:targets){JSONObject t=(JSONObject)item,e=t.getJSONObject("endpoint"),next=new JSONObject();next.put("endpoint",Endpoint.parse(join(e.getString("host"),integer(e,"port",0))).json());next.put("weight",integer(t,"weight",1));canonical.add(next);}targets=canonical;}
        String[] ids=spec.getName().split("_");long uid=Long.parseLong(ids[1]),permission=Long.parseLong(ids[2]);Policies policy=policies(node);long[] user=policy.groups().getOrDefault("user:"+uid,new long[2]),tunnel=policy.groups().getOrDefault("userTunnel:"+permission,new long[2]);long speed=policy.speeds().getOrDefault(spec.getLimiter(),0L);tunnel=new long[]{minimum(tunnel[0],speed),minimum(tunnel[1],speed)};
        JSONArray ls=listeners(spec,options);boolean advanced=!options.isEmpty()||targets.size()>1||speed>0||user[0]+user[1]+tunnel[0]+tunnel[1]>0||spec.getInterfaceName()!=null&&!spec.getInterfaceName().isBlank();for(Object v:targets){JSONObject endpoint=((JSONObject)v).getJSONObject("endpoint");if(!"ip".equals(endpoint.getString("kind"))||!"ipv4".equals(endpoint.getString("family")))advanced=true;}for(Object v:ls){JSONObject l=(JSONObject)v;if(!"ipv4".equals(l.getString("family")))advanced=true;}if(!spec.getTunnel().getTcpListenAddr().equals(spec.getTunnel().getUdpListenAddr()))advanced=true;
        if(!advanced)return null;EngineCapabilities.require(node,"structuredEndpoint");EngineCapabilities.require(node,"independentProtocols");
        for(Object v:ls)if("ipv6".equals(((JSONObject)v).getString("family")))EngineCapabilities.require(node,"ipv6");
        for(Object v:targets){JSONObject e=((JSONObject)v).getJSONObject("endpoint");if("hostname".equals(e.getString("kind")))EngineCapabilities.require(node,"dns");if("ipv6".equals(e.getString("family")))EngineCapabilities.require(node,"ipv6");}
        if(targets.size()>1||options.containsKey("health"))EngineCapabilities.require(node,"multiTarget");
        JSONObject data=new JSONObject();data.put("schemaVersion",options.containsKey("traffic")?4:3);
        if(options.containsKey("traffic")){EngineCapabilities.require(node,"trafficPolicy");JSONObject t=options.getJSONObject("traffic");for(String key:List.of("localOutput","localTargets"))if(t.getBooleanValue(key))EngineCapabilities.require(node,key);if("preserve".equals(t.getString("sourceMode")))EngineCapabilities.require(node,"preserveSource");data.put("traffic",t);}
        data.put("listeners",ls);data.put("targets",targets);String selection=options.getString("selection");if(selection==null)selection=spec.getStrategy();if(selection==null||selection.isBlank())selection="fifo";if(selection.equals("rand"))selection="random";data.put("selection",selection);
        for(String key:List.of("dnsPolicy","health","egress"))if(options.containsKey(key))data.put(key,options.get(key));
        if(spec.getInterfaceName()!=null&&!spec.getInterfaceName().isBlank()){JSONObject e=data.getJSONObject("egress");if(e==null)e=new JSONObject();if(e.containsKey("interface")&&!spec.getInterfaceName().equals(e.getString("interface")))throw new IllegalArgumentException("conflicting egress interfaces");e.put("interface",spec.getInterfaceName());data.put("egress",e);}
        if(data.containsKey("egress"))EngineCapabilities.require(node,"interfaceRouting");
        JSONObject bandwidth=options.getJSONObject("bandwidth");if(bandwidth==null)bandwidth=new JSONObject();if(user[0]+user[1]+tunnel[0]+tunnel[1]>0||!bandwidth.isEmpty()){EngineCapabilities.require(node,"shaping");JSONObject u=new JSONObject();u.put("id","u_"+uid);u.put("upBitsPerSecond",user[0]);u.put("downBitsPerSecond",user[1]);JSONObject t=new JSONObject();t.put("id","ut_"+uid+"_"+permission);t.put("upBitsPerSecond",tunnel[0]);t.put("downBitsPerSecond",tunnel[1]);bandwidth.put("user",u);bandwidth.put("tunnel",t);data.put("bandwidth",bandwidth);}
        if(data.containsKey("traffic")){JSONObject t=data.getJSONObject("traffic");if((t.getBooleanValue("localOutput")||t.getBooleanValue("localTargets"))&&data.containsKey("bandwidth")){JSONObject b=data.getJSONObject("bandwidth");boolean limited=rate(b,"upBitsPerSecond")>0||rate(b,"downBitsPerSecond")>0;for(String key:List.of("user","tunnel")){JSONObject g=b.getJSONObject(key);if(g!=null&&(g.getLongValue("upBitsPerSecond")>0||g.getLongValue("downBitsPerSecond")>0))limited=true;}if(limited&&!reconcile)throw new IllegalArgumentException("local traffic with smooth/shared shaping is not yet supported");}}
        data.put("intentHash",NodeCredentials.hash(com.alibaba.fastjson.JSON.toJSONString(data,com.alibaba.fastjson.serializer.SerializerFeature.MapSortField)));
        return data;
    }
    private static long minimum(long a,long b){return a==0?b:b==0?a:Math.min(a,b);}
}
